// SofiaPlan DTM, valid 2024-10-01. Original 1 m grid and Baltic 1982 heights retained.
// EPSG:7801 horizontal; EPSG:5786 vertical. Display normalization only.
// Sources: https://sofiaplan.bg/api/ and https://api.sofiaplan.bg/datasets/656

var POINT_ASSET = 'projects/rivertracker-512606/assets/sofia_infrastructure_pps';
var GRID_CRS = 'EPSG:7801'; // Native BGS2005 / CCS2005, metres.
var GRID_TRANSFORM = [1, 0, 299392, 0, -1, 4753611];
var DTM_ASSET = 'projects/rivertracker-512606/assets/sofia_dtm_2024_1m_gee';
var points = ee.FeatureCollection(POINT_ASSET);
var area = ee.Geometry.Rectangle([23.0, 42.4, 23.7, 42.95], null, false);
var referenceURL = 'https://en-ca.topographic-map.com/map-lggrf3/Sofia/?center=42.75068%2C23.30135&zoom=14';
Map.setOptions('TERRAIN');
Map.setCenter(23.30135, 42.75068, 14);
var sourceLabel = 'SofiaPlan municipal DTM | original 1 m grid';
var statisticsScale = 10;
var uploadedDtm = ee.Image(DTM_ASSET);
print('Actual uploaded DTM band names', uploadedDtm.bandNames());
print('Actual uploaded DTM projection', uploadedDtm.select([0]).projection());
print('Actual uploaded DTM transform', uploadedDtm.select([0]).projection().transform());
var dem = uploadedDtm.select([0], ['elevation']);
var nativeElevation = dem.updateMask(dem.neq(-9999)).toFloat().clip(area);
var elevation = nativeElevation;
var hillshade = ee.Terrain.hillshade(elevation, 315, 45).clip(area);
var palette = ['0b4da2', '27a7df', '6ddcc7', '83ca42', 'd7e865',
  'fff2a3', 'f6bd60', 'e76f51', 'b53252'];
var elevationLayer = ui.Map.Layer(nativeElevation.unitScale(400, 2400),
  {min: 0, max: 1, palette: palette},
  'Elevation | native 1 m grid | ' + sourceLabel, true, 0.95);
var hillshadeLayer = ui.Map.Layer(hillshade, {min: 0, max: 255},
  'Hillshade | native 1 m DTM', true, 0.22);
Map.layers().add(elevationLayer);
Map.layers().add(hillshadeLayer);
var categories = [
  {code: 1, label: 'Unknown', color: 'bdbdbd', count: 0, shown: false},
  {code: 2, label: 'Water supply', color: '00c8ff', count: 40994, shown: false},
  {code: 3, label: 'Sewerage', color: 'ff9f1c', count: 70790, shown: false},
  {code: 4, label: 'Collectors', color: 'e76f51', count: 1050, shown: false},
  {code: 5, label: 'Power network', color: 'ffeb3b', count: 116844, shown: false},
  {code: 6, label: 'Low-current network', color: 'c77dff', count: 81336, shown: false},
  {code: 7, label: 'District heating / steam', color: 'ff4d6d', count: 10928, shown: false}
];
var infrastructurePanel = ui.Panel({
  style: {position: 'bottom-left', width: '330px', padding: '10px'}
});
infrastructurePanel.add(ui.Label('Sofia infrastructure',
  {fontSize: '18px', fontWeight: 'bold'}));
infrastructurePanel.add(ui.Label('322,025 source points. Toggle each layer.',
  {fontSize: '12px'}));
function addCategoryLayer(subset, label, color, count, shown) {
  var layer = ui.Map.Layer(subset, {color: color},
    'Infrastructure | ' + label, shown);
  Map.layers().add(layer);
  var row = ui.Panel({layout: ui.Panel.Layout.flow('horizontal')});
  row.add(ui.Label('', {backgroundColor: '#' + color,
    padding: '7px', margin: '5px 5px 0 0'}));
  row.add(ui.Checkbox({label: label + ' (' + count.toLocaleString('en-US') + ')',
    value: shown, onChange: function(value) {layer.setShown(value);}}));
  infrastructurePanel.add(row);
}
categories.forEach(function(category) {
  var subset = points.filter(ee.Filter.inList('type',
    [category.code, String(category.code)]));
  addCategoryLayer(subset, category.label, category.color,
    category.count, category.shown);
});
var unspecified = points.filter(ee.Filter.notNull(['type']).not());
addCategoryLayer(unspecified, 'Unspecified in source', 'ffffff', 83, false);
infrastructurePanel.add(ui.Label('Points do not define pipe routes or connections.',
  {fontSize: '11px', color: '666666'}));
Map.add(infrastructurePanel);
var terrainPanel=ui.Panel({style:{position:'bottom-right',width:'320px',padding:'10px'}});
terrainPanel.add(ui.Label('Topography',{fontWeight:'bold',fontSize:'17px'}));
terrainPanel.add(ui.Label('Original 1 m DTM | Baltic 1982 heights (m)',{fontSize:'11px'}));
terrainPanel.add(ui.Checkbox({label:'Elevation colours',value:true,
  onChange:function(v){elevationLayer.setShown(v);}}));
terrainPanel.add(ui.Checkbox({label:'Hillshade',value:true,
  onChange:function(v){hillshadeLayer.setShown(v);}}));
var lastLegend='Temporary scale: 400-2400 m';
var legend=ui.Label(lastLegend,{fontSize:'12px'});
terrainPanel.add(legend);
terrainPanel.add(ui.Thumbnail({
  image:ee.Image.pixelLonLat().select('longitude'),
  params:{region:ee.Geometry.Rectangle([0,0,1,0.04],null,false),
    dimensions:'256x12',min:0,max:1,palette:palette,format:'png'},
  style:{width:'256px',height:'12px',margin:'4px 0'}
}));
var ticks=ui.Panel({layout:ui.Panel.Layout.flow('horizontal')});
var tickLabels=[];
for(var t=0;t<5;t++){
  var tick=ui.Label('',{fontSize:'10px',width:t===4?'35px':'64px',margin:'0'});
  tickLabels.push(tick);ticks.add(tick);
}
terrainPanel.add(ticks);
terrainPanel.add(ui.Label('Nonlinear scale in metres. Extra contrast in flatter terrain.',
  {fontSize:'11px',color:'666666'}));
var fitRequest=0,autoFit=false,wholeAreaValues=null;
var percentiles=[];
for(var p=0;p<=200;p++)percentiles.push(p/2);
var percentileNames=percentiles.map(function(p,i){return 'q'+i;});
function applyColours(values,scope){
  var low=values.elevation_q0,high=values.elevation_q200,x=[],y=[];
  for(var i=0;i<=200;i++){
    var v=values['elevation_q'+i];
    if(!x.length||v>x[x.length-1]){
      x.push(v);
      y.push(high>low?0.8*i/200+0.2*(v-low)/(high-low):0.5);
    }
  }
  if(x.length<2){x=[low-0.5,low+0.5];y=[0,1];}
  else{y[0]=0;y[y.length-1]=1;}
  elevationLayer.setEeObject(nativeElevation.interpolate(x,y,'clamp'));
  elevationLayer.setVisParams({min:0,max:1,palette:palette});
  for(var j=0;j<5;j++){
    var level=j/4,k=1;
    while(k<y.length-1&&y[k]<level)k++;
    var height=x[k-1]+(level-y[k-1])/(y[k]-y[k-1])*(x[k]-x[k-1]);
    tickLabels[j].setValue(height.toFixed(1));
  }
  lastLegend=scope+' | normalized '+low.toFixed(1)+'-'+high.toFixed(1)+' m';
  legend.setValue(lastLegend);
}
function fitColours(region,scope,whole){
  var request=++fitRequest;
  fitButton.setDisabled(true);wholeButton.setDisabled(true);
  legend.setValue('Reading elevation distribution...');
  nativeElevation.reduceRegion({
    reducer:ee.Reducer.percentile(percentiles,percentileNames,65536,0.05,4096),
    geometry:region.intersection(area,30),scale:whole?60:statisticsScale,
    bestEffort:true,maxPixels:2000000,tileScale:4
  }).evaluate(function(values,error){
    if(request!==fitRequest)return;
    fitButton.setDisabled(false);wholeButton.setDisabled(false);
    var valid=!error&&values;
    for(var i=0;valid&&i<=200;i++){
      var value=values['elevation_q'+i];
      if(typeof value!=='number'||!isFinite(value))valid=false;
    }
    if(!valid){legend.setValue((error?'Colour statistics unavailable. ':'No valid terrain in this view. ')+lastLegend);return;}
    if(whole)wholeAreaValues=values;
    applyColours(values,scope);
  });
}
function fitLocal(){fitColours(ee.Geometry(Map.getBounds(true)),'Current view',false);}
var fitButton=ui.Button({label:'Fit colours to current view',onClick:fitLocal,
  style:{stretch:'horizontal'}});
var wholeButton=ui.Button({label:'Use whole-area scale',onClick:function(){
  ++fitRequest;fitButton.setDisabled(false);wholeButton.setDisabled(false);
  if(wholeAreaValues)applyColours(wholeAreaValues,'Whole area');
  else fitColours(area,'Whole area',true);
},style:{stretch:'horizontal'}});
terrainPanel.add(fitButton);terrainPanel.add(wholeButton);
terrainPanel.add(ui.Checkbox({label:'Auto-fit when panning / zooming',value:false,
  onChange:function(v){autoFit=v;if(v)fitLocal();}}));
Map.onChangeBounds(ui.util.debounce(function(){if(autoFit)fitLocal();},600));
var clickLabel=ui.Label('Click the map to read elevation.',{fontSize:'12px'});
terrainPanel.add(clickLabel);
terrainPanel.add(ui.Label({value:'Original topographic map reference',targetUrl:referenceURL,
  style:{fontSize:'11px',color:'1565c0'}}));
Map.add(terrainPanel);
fitColours(area,'Whole area',true);
var clickRequest = 0;
Map.onClick(function(coords) {
  var request = ++clickRequest;
  var location = ee.Geometry.Point([coords.lon, coords.lat]);
  clickLabel.setValue('Reading elevation...');
  elevation.reduceRegion({reducer: ee.Reducer.first(), geometry: location,
    crs: GRID_CRS, crsTransform: GRID_TRANSFORM, maxPixels: 1000
  }).evaluate(function(values, error) {
    if (request !== clickRequest) return;
    clickLabel.setValue(!error && values && typeof values.elevation === 'number' ?
      'Elevation: ' + values.elevation.toFixed(1) + ' m' : 'No elevation here.');
  });
  print('Up to 10 infrastructure points within 25 m',
    points.filterBounds(location.buffer(25)).limit(10));
});
print('Infrastructure points (expected 322025)', points.size());
print('Points without a category (expected 83)', unspecified.size());
print('Category counts', points.aggregate_histogram('type'));
print('Elevation source', sourceLabel);
print('Output grid', elevation.projection());
print('Output cell size in metres', elevation.projection().nominalScale());
var CREATE_EXPORT_TASK = false;
if (CREATE_EXPORT_TASK) {
Export.image.toDrive({
  image: elevation,
  description: 'SofiaPlan_DTM_2024_1m',
  folder: 'GEE_Sofia',
  region: area,
  crs: GRID_CRS,
  crsTransform: GRID_TRANSFORM,
  maxPixels: 5000000000,
  fileDimensions: 8192,
  shardSize: 256,
  skipEmptyTiles: true,
  fileFormat: 'GeoTIFF',
  formatOptions: {cloudOptimized: true}
});
}

