var vectorBundle = require('users/yoantrendafilov2002/rivertracker:Script2').unpack(PACKED_FIRST);
var ROUTE_SOURCE=vectorBundle[0];
var ROUTE_GEOMETRIES=vectorBundle[1];
var GREEN_GEOMETRIES=vectorBundle[2];
function decodePath(encoded) {
  var pos = 0, last = [23000000000, 42000000000], path = [];
  while (pos < encoded.length) {
    var xy = [];
    for (var axis = 0; axis < 2; axis++) {
      var value = 0, factor = 1, digit;
      do {
        digit = encoded.charCodeAt(pos++) - 63;
        value += (digit & 31) * factor;
        factor *= 32;
      } while (digit >= 32);
      var delta = value % 2 ? -(value + 1) / 2 : value / 2;
      last[axis] += delta;
      xy.push(last[axis] / 1e9);
    }
    path.push(xy);
  }
  return path;
}
var routeParts = ee.FeatureCollection(ROUTE_GEOMETRIES.map(function(row) {
  var source = ROUTE_SOURCE[row[0]];
  var status = source[3].indexOf('проект') >= 0 ? 'planned' :
    (source[3].indexOf('Открит') >= 0 ? 'open' : 'existing');
  return ee.Feature(ee.Geometry.MultiLineString(row[3].map(decodePath), 'EPSG:4326', false), {
    object_id: source[0], source_id: source[1], leg: source[2], legso: source[3],
    status: status, zone: ['all', 'inside', 'outside'][row[1]], length_m: row[2]
  });
}));

var greenAreas = ee.FeatureCollection(GREEN_GEOMETRIES.map(function(polygons) {
  return ee.Feature(ee.Geometry.MultiPolygon(polygons.map(function(rings) {
    return rings.map(decodePath);
  }), 'EPSG:4326', false));
}));

var greenLayer=ui.Map.Layer(greenAreas.style({color:'246b35',fillColor:'52c46850',width:1}),{},'Green areas intersecting routes | 2020',true);
Map.layers().insert(2,greenLayer);
var routeZone = 'inside';
var routeTypes = [
  {status:'existing',label:'Existing routes',color:'00e5ff',lineType:'solid'},
  {status:'planned',label:'Planned routes',color:'ff4dce',lineType:'dashed'},
  {status:'open',label:'Open channels',color:'ffeb3b',lineType:'solid'}
];
var routePanel=ui.Panel({style:{position:'top-center',width:'290px',padding:'8px'}});
routePanel.add(ui.Label('Sewer routes | green-area mask',{fontSize:'16px',fontWeight:'bold'}));
routePanel.add(ui.Label('Route sections shown:',{fontSize:'12px'}));
var routeStats=ui.Label('',{fontSize:'12px'});
function refreshRoutes() {
  var selected=routeParts.filter(ee.Filter.eq('zone',routeZone));
  var active=[];
  routeTypes.forEach(function(type) {
    type.layer.setEeObject(selected.filter(ee.Filter.eq('status',type.status))
      .style({color:type.color,width:3,lineType:type.lineType}));
    if(type.layer.getShown())active.push(type.status);
  });
  var zoneIndex=['all','inside','outside'].indexOf(routeZone);
  var count=0,length=0;
  ROUTE_GEOMETRIES.forEach(function(row) {
    if(row[1]!==zoneIndex)return;
    var legso=ROUTE_SOURCE[row[0]][3];
    var status=legso.indexOf('проект')>=0?'planned':(legso.indexOf('Открит')>=0?'open':'existing');
    if(active.indexOf(status)>=0){count++;length+=row[2];}
  });
  routeStats.setValue(count+' source routes | '+(length/1000).toFixed(2)+' km');
}
routePanel.add(ui.Select({
  items:[{label:'Inside green areas',value:'inside'},{label:'Outside green areas',value:'outside'},{label:'All routes',value:'all'}],
  value:'inside',style:{stretch:'horizontal'},
  onChange:function(value){routeZone=value;refreshRoutes();}
}));
routeTypes.forEach(function(type) {
  type.layer=ui.Map.Layer(ee.Image(0).selfMask(),{},'Sewer map | '+type.label,true);
  Map.layers().add(type.layer);
  routePanel.add(ui.Checkbox({label:type.label,value:true,
    onChange:function(value){type.layer.setShown(value);refreshRoutes();}}));
});
routePanel.add(ui.Checkbox({label:'Show green polygons along routes',value:true,onChange:function(value){greenLayer.setShown(value);}}));
routePanel.add(routeStats);
routePanel.add(ui.Label('Cyan: existing | Magenta dashed: planned | Yellow: open',{fontSize:'10px'}));
routePanel.add(ui.Label('Mask: all 64,956 nonempty green-area polygons.',{fontSize:'11px'}));
routePanel.add(ui.Label('Routes: 2009 source | Green areas: 2020 source',{fontSize:'11px',color:'666666'}));
Map.add(routePanel);
refreshRoutes();
print('Original sewer routes (expected 717)',routeParts.filter(ee.Filter.eq('zone','all')).size());
print('Route status from source',routeParts.filter(ee.Filter.eq('zone','all')).aggregate_histogram('status'));
